using Gtk 4.0;
using Adw 1;

template $GraphsAddEquationDialog: Adw.Dialog {
  content-width: 450;
  title: _("Add Equation");
  default-widget: confirm_button;
  focus-widget: confirm_button;

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      show-end-title-buttons: false;

      [start]
      Button {
        label: _("Cancel");
        action-name: "window.close";
      }

      [end]
      Button confirm_button {
        label: _("Add");
        clicked => $on_accept();

        styles [
          "suggested-action",
        ]
      }
    }

    content: ScrolledWindow {
      propagate-natural-height: true;

      child: Viewport {
        child: Adw.Clamp {
          margin-start: 12;
          margin-end: 12;
          margin-top: 12;
          margin-bottom: 12;

          Adw.PreferencesGroup {
            separate-rows: true;
            description: _("Enter a mathematical expression");

            Adw.EntryRow equation {
              max-width-chars: 25;
              title: _("Y =");
              activates-default: true;
              notify::text => $on_equation_change();

              styles [
                "preferencesgroup",
              ]
            }

            Adw.EntryRow item_name {
              max-width-chars: 25;
              title: _("Name (optional)");
              activates-default: true;
            }
          }
        };
      };
    };
  };
}

using Gtk 4.0;
using Adw 1;

template $GraphsCurveFittingDialog: Adw.Dialog {
  content-width: 1000;
  content-height: 600;
  width-request: 360;
  height-request: 100;
  focus-widget: confirm_button;

  ShortcutController {
    Shortcut {
      trigger: "F9";
      action: "action(win.toggle_sidebar)";
    }
  }

  Adw.Breakpoint {
    condition ("max-width: 675sp")

    setters {
      split_view.collapsed: true;
    }
  }

  Adw.Breakpoint {
    condition ("max-height: 500sp")

    setters {
      residuals_container.height-request: 150;
    }
  }

  child: Adw.ToolbarView {
    top-bar-style: flat;

    content: Adw.OverlaySplitView split_view {
      enable-show-gesture: bind split_view.collapsed;
      enable-hide-gesture: bind split_view.collapsed;

      sidebar: Adw.ToolbarView {
        [top]
        Adw.HeaderBar {
          title-widget: Adw.WindowTitle {
            title: _("Curve Fitting");
          };

          [end]
          MenuButton {
            icon-name: "view-more-symbolic";
            tooltip-text: _("Open Curve Fitting Menu");
            primary: true;
            menu-model: fitting_menu;
          }
        }

        content: Box {
          orientation: vertical;

          ScrolledWindow {
            vexpand: true;
            width-request: 280;
            hscrollbar-policy: never;

            Box {
              orientation: vertical;
              margin-start: 12;
              margin-end: 12;
              margin-bottom: 12;
              margin-top: 12;
              spacing: 12;

              Adw.PreferencesGroup {
                Adw.ComboRow equation {
                  title: _("Equation");

                  model: StringList {
                    strings [
                      C_("regression-type", "Linear"),
                      C_("regression-type", "Quadratic"),
                      C_("regression-type", "Exponential"),
                      C_("regression-type", "Power Law"),
                      C_("regression-type", "Logarithmic"),
                      C_("regression-type", "Sigmoid Logistic"),
                      C_("regression-type", "Gaussian"),
                      C_("regression-type", "Custom"),
                    ]
                  };
                }

                Adw.EntryRow custom_equation {
                  visible: false;
                  title: _("Y =");
                }
              }

              Box fitting_params_box {
                hexpand: true;
                spacing: 12;
                orientation: vertical;
              }

              ScrolledWindow {
                hexpand: true;
                hscrollbar-policy: automatic;
                vscrollbar-policy: never;
                propagate-natural-height: true;

                TextView text_view {
                  left-margin: 12;
                  right-margin: 12;
                  top-margin: 12;
                  bottom-margin: 12;
                  halign: fill;
                  editable: false;

                  styles [
                    "card",
                  ]
                }
              }
            }
          }
        };

        [bottom]
        Adw.Clamp {
          maximum-size: 400;

          child: Box {
            margin-start: 12;
            margin-end: 12;
            margin-top: 6;
            margin-bottom: 12;

            Button confirm_button {
              hexpand: true;
              label: _("Add Fit to Data");
              clicked => $on_accept();

              styles [
                "pill",
                "suggested-action",
              ]
            }
          };
        }
      };

      content: Adw.ToolbarView {
        styles [
          "system-canvas-view",
        ]

        [top]
        Adw.HeaderBar {
          show-title: false;

          ToggleButton show_sidebar_button {
            icon-name: "sidebar-show-symbolic";
            tooltip-text: _("Toggle Sidebar");
            active: bind split_view.show-sidebar bidirectional;
            visible: bind split_view.collapsed;
          }
        }

        content: Adw.ToastOverlay toast_overlay {
          focusable: true;
          hexpand: true;

          child: Box {
            orientation: vertical;
            hexpand: true;
            vexpand: true;

            Adw.Bin canvas_container {
              hexpand: true;
              vexpand: true;

              Adw.StatusPage {
                visible: false;
                icon-name: "dialog-error-symbolic";
                title: _("Canvas Failed to Load");
              }
            }

            Adw.Bin residuals_container {
              hexpand: true;
              vexpand: false;
              height-request: 200;
              visible: false;
            }
          };
        };
      };
    };
  };
}

menu fitting_menu {
  section {
    label: _("Optimization Method");

    item {
      // Translators: see https://help.gnome.org/graphs/curve_fitting.html#algorithms
      label: C_("optimization", "Levenberg-Marquardt");
      action: "win.optimization";
      target: "lm";
    }

    item {
      // Translators: see https://help.gnome.org/graphs/curve_fitting.html#algorithms, NOTE: This is a reflective version of the Trust-region algorithm.
      label: C_("optimization", "Trust Region Reflective");
      action: "win.optimization";
      target: "trf";
    }

    item {
      // Translators: see https://help.gnome.org/graphs/curve_fitting.html#algorithms
      label: C_("optimization", "Dogbox");
      action: "win.optimization";
      target: "dogbox";
    }
  }

  section {
    label: _("Confidence Bounds");

    item {
      label: C_("confidence", "None");
      action: "win.confidence";
      target: "none";
    }

    item {
      /* xgettext: no-c-format */
      label: C_("confidence", "1σ: 68% Confidence");
      action: "win.confidence";
      target: "1std";
    }

    item {
      /* xgettext: no-c-format */
      label: C_("confidence", "2σ: 95% Confidence");
      action: "win.confidence";
      target: "2std";
    }

    item {
      /* xgettext: no-c-format */
      label: C_("confidence", "3σ: 99.7% Confidence");
      action: "win.confidence";
      target: "3std";
    }
  }

  section {
    item {
      label: _("Show Residuals");
      action: "win.show-residuals";
    }
  }
}

using Gtk 4.0;
using Adw 1;

template $GraphsExportFigureDialog: Adw.Dialog {
  content-width: 450;
  title: _("Export Figure");
  focus-widget: confirm_button;

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      show-end-title-buttons: false;

      [start]
      Button {
        label: _("Cancel");
        action-name: "window.close";
      }

      [end]
      Button confirm_button {
        label: _("Export");
        clicked => $on_accept();

        styles [
          "suggested-action",
        ]
      }
    }

    content: Adw.Clamp {
      maximum-size: 800;
      margin-bottom: 12;
      margin-top: 12;
      margin-start: 12;
      margin-end: 12;

      child: Box {
        orientation: vertical;
        spacing: 10;

        Adw.PreferencesGroup {
          title: _("Export Settings");

          Adw.ComboRow file_format {
            title: _("File Format");

            model: StringList {
              strings [
                C_("file-format", "Encapsulated PostScript"),
                C_("file-format", "JPEG"),
                C_("file-format", "PDF"),
                C_("file-format", "PNG"),
                C_("file-format", "PostScript"),
                C_("file-format", "SVG"),
                C_("file-format", "WebP"),
              ]
            };
          }

          Adw.SwitchRow transparent {
            title: _("Transparent Background");
          }
        }

        Adw.PreferencesGroup {
          title: _("Export Size");

          Adw.SpinRow width {
            title: _("Width (pixels)");

            adjustment: Adjustment {
              step-increment: 10;
              lower: 100;
              upper: 7680;
            };
          }

          Adw.SpinRow height {
            title: _("Height (pixels)");

            adjustment: Adjustment {
              step-increment: 10;
              lower: 100;
              upper: 4320;
            };
          }

          Adw.ButtonRow {
            title: _("Use Same Size as App");
            activated => $on_use_window_size();
          }
        }
      };
    };
  };
}

using Gtk 4.0;
using Adw 1;

template $GraphsFittingParameterBox: Box {
  orientation: vertical;

  Grid {
    column-homogeneous: true;
    margin-bottom: 3;
    margin-top: 3;
    column-spacing: 4;
    row-spacing: 4;

    Label label {
      justify: left;
      use-markup: true;
      margin-bottom: 4;
      hexpand: false;
      halign: start;

      layout {
        column: 0;
        row: 0;
        column-span: 2;
      }
    }

    Adw.PreferencesGroup {
      Adw.EntryRow initial {
        title: _("Initial Guess");
        text: "1";
      }

      layout {
        column: 0;
        row: 1;
        column-span: 2;
      }
    }

    Adw.PreferencesGroup {
      visible: bind lower_bound.visible;

      Adw.EntryRow lower_bound {
        title: _("Minimum");
        text: "-inf";
      }

      layout {
        column: 0;
        row: 2;
      }
    }

    Adw.PreferencesGroup {
      visible: bind upper_bound.visible;

      Adw.EntryRow upper_bound {
        title: _("Maximum");
        text: "inf";
      }

      layout {
        column: 1;
        row: 2;
      }
    }
  }
}

using Gtk 4.0;
using Adw 1;

template $GraphsGenerateDataDialog: Adw.Dialog {
  content-width: 450;
  title: _("Generate Data");
  default-widget: confirm_button;
  focus-widget: confirm_button;

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      show-end-title-buttons: false;

      [start]
      Button {
        label: _("Cancel");
        action-name: "window.close";
      }

      [end]
      Button confirm_button {
        label: _("Generate");
        clicked => $on_accept();

        styles [
          "suggested-action",
        ]
      }
    }

    content: ScrolledWindow {
      propagate-natural-height: true;

      child: Viewport {
        child: Adw.Clamp {
          margin-start: 12;
          margin-end: 12;
          margin-top: 12;
          margin-bottom: 12;

          Box {
            spacing: 20;
            orientation: vertical;

            Adw.PreferencesGroup {
              separate-rows: true;
              description: _("Enter a mathematical expression");

              Adw.EntryRow equation {
                max-width-chars: 25;
                title: _("Y =");
                activates-default: true;
                notify::text => $on_equation_change();
              }

              Adw.EntryRow item_name {
                max-width-chars: 25;
                title: _("Name (optional)");
                activates-default: true;
              }
            }

            Adw.PreferencesGroup {
              Box {
                spacing: 12;
                orientation: horizontal;
                homogeneous: true;

                Adw.PreferencesGroup {
                  Adw.EntryRow xstart {
                    title: _("X Start");
                    notify::text => $on_entry_change();
                  }
                }

                Adw.PreferencesGroup {
                  Adw.EntryRow xstop {
                    title: _("X Stop");
                    notify::text => $on_entry_change();
                  }
                }
              }
            }

            Adw.PreferencesGroup {
              Adw.SpinRow steps {
                title: _("Steps");
                input => $on_steps_input();

                adjustment: Adjustment {
                  step-increment: 1;
                  page-increment: 100;
                  lower: 2;
                  upper: 1000000000;
                };
              }

              Adw.ComboRow scale {
                title: _("Scale");
                subtitle: _("How points are spaced");

                model: StringList {
                  strings [
                    C_("scale", "Linear"),
                    C_("scale", "Logarithmic (Base 10)"),
                    C_("scale", "Logarithmic (Base 2)"),
                    C_("scale", "Radians"),
                    C_("scale", "Square Root"),
                    C_("scale", "Inverse"),
                  ]
                };
              }
            }
          }
        };
      };
    };
  };
}

using Gtk 4.0;
using Adw 1;

template $GraphsItemBox: Adw.ActionRow {
  title-lines: 1;
  activatable: true;

  [prefix]
  CheckButton check_button {
    halign: start;
    notify::active => $on_toggle();

    styles [
      "selection-mode",
    ]
  }

  [suffix]
  Button color_button {
    tooltip-text: _("Pick Color");
    vexpand: false;
    valign: center;
    clicked => $choose_color();

    styles [
      "flat",
    ]

    Image {
      icon-name: "color-picker-symbolic";
      pixel-size: 20;
    }
  }

  [suffix]
  MenuButton {
    icon-name: "view-more-symbolic";
    vexpand: false;
    valign: center;

    styles [
      "flat",
    ]

    popover: PopoverMenu {
      has-arrow: false;
      menu-model: item_menu;
    };
  }
}

menu item_menu {
  section {
    label: _("Move Item");
    display-hint: "inline-buttons";

    item {
      verb-icon: "down-symbolic";
      action: "item_box.move_down";
    }

    item {
      verb-icon: "up-symbolic";
      action: "item_box.move_up";
    }
  }

  section {
    item {
      label: _("Curve Fitting");
      action: "item_box.curve_fitting";
    }

    item {
      label: _("Remove Item");
      action: "item_box.delete";
    }
  }
}

using Gtk 4.0;
using Adw 1;

template $GraphsSmoothenDialog: Adw.Dialog {
  content-width: 640;
  content-height: 576;
  title: _("Smoothen Settings");
  focus-widget: reset_button;

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      [start]
      Button reset_button {
        icon-name: "history-undo-symbolic";
        clicked => $on_reset();
      }
    }

    content: ScrolledWindow {
      propagate-natural-height: true;

      child: Viewport {
        child: Adw.Clamp {
          margin-start: 12;
          margin-end: 12;
          margin-top: 12;
          margin-bottom: 12;

          Box {
            orientation: vertical;
            spacing: 10;

            Adw.PreferencesGroup {
              title: _("Savitzky–Golay Filter");

              Adw.SpinRow savgol_window {
                title: _("Span percentage");
                subtitle: _("What percentage of the data span to use for the filter window");

                adjustment: Adjustment {
                  step-increment: 1;
                  upper: 99;
                };
              }

              Adw.SpinRow savgol_polynomial {
                title: _("Polynomial degree");

                adjustment: Adjustment {
                  step-increment: 1;
                  upper: 20;
                };
              }
            }

            Adw.PreferencesGroup {
              title: _("Moving Average");

              Adw.SpinRow moving_average_box {
                title: _("Box points");
                subtitle: _("Amount of points to use when calculating a moving average");

                adjustment: Adjustment {
                  step-increment: 1;
                  upper: 9999;
                };
              }
            }
          }
        };
      };
    };
  };
}

using Gtk 4.0;
using Adw 1;

template $GraphsStylePreview: Adw.Bin {
  child: AspectFrame {
    child: Box {
      orientation: vertical;

      Overlay {
        height-request: 93;
        width-request: 155;

        [overlay]
        Image {
          halign: end;
          valign: end;
          margin-end: 6;
          margin-bottom: 6;
          icon-name: "check-round-outline-whole-symbolic";
          name: "indicator";
        }

        [overlay]
        MenuButton menu_button {
          visible: false;
          icon-name: "view-more-symbolic";
          halign: end;
          valign: start;
          margin-end: 4;
          margin-top: 4;
          menu-model: style_menu;

          styles [
            "flat",
          ]
        }

        child: Picture picture {};
      }

      Label label {
        margin-top: 8;
        ellipsize: end;
      }
    };
  };
}

menu style_menu {
  section {
    item {
      label: _("Open");
      action: "style.open";
    }

    item {
      label: _("Open With…");
      action: "style.open_with";
    }

    item {
      label: _("Delete…");
      action: "style.delete";
    }
  }
}

using Gtk 4.0;
using Adw 1;

template $GraphsTransformDialog: Adw.Dialog {
  content-width: 450;
  title: _("Transform Data");
  default-widget: confirm_button;
  focus-widget: confirm_button;

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      show-end-title-buttons: false;

      [start]
      Button {
        label: _("Cancel");
        action-name: "window.close";
      }

      [end]
      Button confirm_button {
        label: _("Transform");
        clicked => $on_accept();

        styles [
          "suggested-action",
        ]
      }

      [end]
      MenuButton {
        halign: end;
        icon-name: "info-symbolic";
        tooltip-text: _("More info");

        popover: Popover {
          position: bottom;

          Label {
            label: _("<b>Available variables</b>\nGeneral:\n counts - number of data points\n\nX-Axis:\n x_min, x_max - minimum and maximum values,\n x_mean, x_median - average and median,\n x_std, x_sum — standard deviation and sum\n\nY-Axis:\n y_min, y_max - minimum and maximum,\n y_mean, y_median — average and median,\n y_std, y_sum - standard deviation and sum\n\nTrigonometric functions use radians by default.\nAppend d to use degrees, e.g. sind(x) or cosd(x).");
            use-markup: true;
            margin-top: 12;
            margin-bottom: 12;
            margin-start: 12;
            margin-end: 12;
          }
        };
      }
    }

    content: ScrolledWindow {
      propagate-natural-height: true;

      child: Viewport {
        child: Adw.Clamp {
          margin-start: 12;
          margin-end: 12;
          margin-top: 12;
          margin-bottom: 12;

          Adw.PreferencesGroup {
            Adw.EntryRow transform_x {
              title: _("X =");
              activates-default: true;
            }

            Adw.EntryRow transform_y {
              title: _("Y =");
              activates-default: true;
            }

            Adw.SwitchRow discard {
              title: _("Discard Unselected Data");
            }
          }
        };
      };
    };
  };
}

