using Gtk 4.0;
using Adw 1;

template $GraphsImportDialog: Adw.Dialog {
  content-width: 900;
  content-height: 576;
  width-request: 360;
  height-request: 200;
  focus-widget: confirm_button;

  Adw.Breakpoint {
    condition ("max-width: 500sp")

    setters {
      navigation_view.collapsed: true;
    }
  }

  child: Adw.NavigationSplitView navigation_view {
    sidebar: Adw.NavigationPage file_list_page {
      title: _("Import Parameters");
      width-request: 260;

      child: Adw.ToolbarView {
        [top]
        Adw.HeaderBar {
          [start]
          Button {
            icon-name: "list-add-symbolic";
            tooltip-text: _("Add File");
            clicked => $on_add();
          }
        }

        content: ScrolledWindow {
          propagate-natural-height: true;

          child: Viewport {
            child: Adw.Clamp {
              child: Box {
                orientation: vertical;

                ListBox file_list {
                  selection-mode: single;
                  vexpand: true;
                  valign: start;
                  row-activated => $on_row_activated();
                  row-selected => $on_row_selected();

                  styles [
                    "navigation-sidebar",
                  ]
                }

                Button confirm_button {
                  label: _("Import");
                  margin-start: 12;
                  margin-end: 12;
                  margin-top: 12;
                  margin-bottom: 12;
                  clicked => $on_accept();

                  styles [
                    "suggested-action",
                    "pill",
                  ]
                }
              };
            };
          };
        };
      };
    };

    content: Adw.NavigationPage file_settings_page {
      title: "tmp";

      child: Adw.ToolbarView {
        [top]
        Adw.HeaderBar {
          [end]
          Button {
            icon-name: "history-undo-symbolic";
            tooltip-text: _("Reset to guessed values");
            clicked => $on_reset();
          }
        }

        content: Adw.ToastOverlay toast_overlay {
          child: ScrolledWindow {
            propagate-natural-height: true;

            child: Viewport {
              child: Adw.Clamp {
                margin-start: 12;
                margin-end: 12;
                margin-top: 12;
                margin-bottom: 12;

                Box {
                  orientation: vertical;
                  spacing: 10;

                  Adw.PreferencesGroup {
                    Adw.ComboRow mode {
                      title: _("Import Mode");
                      notify::selected => $on_mode();
                    }
                  }

                  Box file_settings_box {
                    orientation: vertical;
                    spacing: 10;
                  }

                  Adw.PreferencesGroup default_group {
                    Adw.ButtonRow {
                      title: _("Set as Default");
                      activated => $set_as_default();
                    }
                  }

                  Adw.PreferencesGroup remove_group {
                    Adw.ButtonRow {
                      title: _("Remove");
                      activated => $remove();

                      styles [
                        "destructive-action",
                      ]
                    }
                  }
                }
              };
            };
          };
        };
      };
    };
  };
}

using Gtk 4.0;

template $GraphsImportFileRow: ListBoxRow {
  activatable: true;

  child: Box {
    margin-start: 3;
    margin-top: 9;
    margin-bottom: 9;
    spacing: 3;

    Label filename {
      hexpand: true;
      halign: start;
      ellipsize: end;
    }

    Label mode {
      styles [
        "import-mode",
      ]
    }
  };
}

using Gtk 4.0;
using Adw 1;

template $GraphsMainSidebarPage: Adw.NavigationPage {
  title: _("Graphs");

  child: Adw.ToolbarView {
    [top]
    Adw.HeaderBar {
      [start]
      MenuButton add_button {
        icon-name: "list-add-symbolic";
        tooltip-text: _("Add New Data");
        always-show-arrow: true;
        menu-model: add_data_menu;
      }

      [end]
      MenuButton {
        icon-name: "open-menu-symbolic";
        menu-model: primary_menu;
        tooltip-text: _("Open Application Menu");
        primary: true;
      }

      [end]
      Button figure_settings_button {
        action-name: "win.figure-settings";
        icon-name: "settings-symbolic";
        tooltip-text: _("Figure Settings");
      }
    }

    ScrolledWindow {
      child: Viewport {
        child: Box {
          orientation: vertical;

          Stack itemlist_stack {
            StackPage {
              child: Adw.StatusPage {
                icon-name: "list-compact";
                title: _("No Data");
                description: _("Add data from a file or manually as an equation");

                styles [
                  "compact",
                ]
              };
            }

            StackPage {
              child: ScrolledWindow scrollwindow_itemlist {
                vexpand: true;
                hexpand: true;
                hscrollbar-policy: never;

                Viewport {
                  ListBox item_list {
                    margin-bottom: 12;
                    margin-top: 6;
                    margin-start: 12;
                    margin-end: 12;
                    vexpand: false;
                    hexpand: true;
                    valign: start;
                    selection-mode: none;

                    styles [
                      "boxed-list",
                    ]
                  }
                }
              };
            }
          }

          Separator {
            orientation: horizontal;
          }

          Box {
            spacing: 10;
            margin-top: 12;
            margin-bottom: 12;
            margin-start: 12;
            margin-end: 12;

            ToggleButton pan_button {
              icon-name: "move-tool-symbolic";
              action-name: "win.mode-pan";
              hexpand: true;
              tooltip-text: _("Pan Mode. Click and drag to pan");
            }

            ToggleButton zoom_button {
              icon-name: "loupe-symbolic";
              action-name: "win.mode-zoom";
              hexpand: true;
              tooltip-text: _("Zoom Mode. Select an area on the figure to zoom in");
            }

            ToggleButton select_button {
              icon-name: "edit-select-all-symbolic";
              action-name: "win.mode-select";
              hexpand: true;
              tooltip-text: _("Select Mode. Click and drag to make a selection of data");
            }
          }

          Separator {
            orientation: horizontal;
          }

          Adw.Bin operations_bin {}
        };
      };
    }
  };
}

menu primary_menu {
  section {
    item (_("New Project"), "app.new-window")
  }

  section {
    item (_("Save Project…"), "win.save-project")
    item (_("Save Project as…"), "win.save-project-as")
    item (_("Open Project…"), "win.open-project")
    item (_("Close Project"), "win.close-project")
  }

  section {
    item (_("Export Data…"), "win.export-data")
    item (_("Export Figure…"), "win.export-figure")
  }

  section {
    item (_("Style Editor"), "app.style-editor")
  }

  section {
    item (_("Keyboard Shortcuts"), "win.show-shortcuts")
    item (_("Help"), "app.help")
    item (_("About Graphs"), "app.about")
  }
}

menu add_data_menu {
  section {
    item (_("Add Data from File…"), "win.add-data")
    item (_("Add Equation…"), "win.add-equation")
    item (_("Generate Data…"), "win.generate-data")
  }
}

using Gtk 4.0;
using Adw 1;

template $GraphsOperations: Box {
  orientation: vertical;
  hexpand: false;
  spacing: 18;
  margin-start: 12;
  margin-end: 12;
  margin-top: 12;
  margin-bottom: 12;

  Adw.InlineViewSwitcher {
    stack: stack;
    homogeneous: true;
  }

  Adw.ViewStack stack {
    Adw.ViewStackPage {
      title: _("Adjust");

      child: Adw.PreferencesGroup {
        Grid {
          column-homogeneous: true;
          column-spacing: 10;
          row-spacing: 10;

          Button combine_button {
            sensitive: bind shift_button.sensitive;
            tooltip-text: _("Combine all selected data");
            clicked => $perform_operation();

            layout {
              column: 0;
              row: 0;
            }

            Adw.ButtonContent {
              halign: center;
              icon-name: "edit-paste-symbolic";
              label: _("Combine");
            }
          }

          Button cut_button {
            tooltip-text: _("Cut selected data");
            clicked => $perform_operation();

            layout {
              column: 1;
              row: 0;
            }

            Adw.ButtonContent {
              halign: center;
              icon-name: "edit-cut-symbolic";
              label: _("Cut");
            }
          }

          Button shift_button {
            tooltip-text: _("Shift all data vertically with respect to each other");
            clicked => $perform_operation();

            layout {
              column: 0;
              row: 1;
            }

            Adw.ButtonContent {
              halign: center;
              icon-name: "shift-symbolic";
              label: _("Shift");
            }
          }

          Button normalize_button {
            sensitive: bind shift_button.sensitive;
            tooltip-text: _("Normalize data");
            clicked => $perform_operation();

            layout {
              column: 1;
              row: 1;
            }

            Adw.ButtonContent {
              halign: center;
              icon-name: "normalize-symbolic";
              label: _("Normalize");
            }
          }

          Adw.SplitButton smoothen_button {
            can-shrink: true;
            tooltip-text: _("Smoothen data");
            menu-model: smoothen_menu;
            clicked => $perform_operation();

            layout {
              column: 0;
              row: 2;
              column-span: 2;
            }

            Adw.ButtonContent {
              halign: center;
              can-shrink: true;
              icon-name: "smoothen-symbolic";
              label: _("Smoothen");
            }
          }

          Adw.SplitButton center_button {
            sensitive: bind shift_button.sensitive;
            tooltip-text: _("Center data");
            menu-model: center_menu;
            clicked => $perform_operation();

            layout {
              column: 0;
              row: 3;
              column-span: 2;
            }

            Adw.ButtonContent {
              halign: center;
              icon-name: "center-symbolic";
              label: _("Center");
            }
          }
        }
      };
    }

    Adw.ViewStackPage {
      title: _("Transform");

      child: Adw.PreferencesGroup {
        Grid {
          column-homogeneous: true;
          column-spacing: 12;
          row-spacing: 12;

          Button derivative_button {
            sensitive: bind shift_button.sensitive;
            tooltip-text: _("Get the derivative of the data");
            clicked => $perform_operation();

            layout {
              column: 0;
              row: 0;
            }

            Adw.ButtonContent {
              halign: center;
              icon-name: "derivative2-symbolic";
              label: _("Derivative");
            }
          }

          Button integral_button {
            sensitive: bind shift_button.sensitive;
            tooltip-text: _("Get the indefinite integral of the data");
            clicked => $perform_operation();

            layout {
              column: 1;
              row: 0;
            }

            Adw.ButtonContent {
              halign: center;
              icon-name: "integral-symbolic";
              label: _("Integral");
            }
          }

          Button fft_button {
            sensitive: bind shift_button.sensitive;
            tooltip-text: _("Get the Fast Fourier Transform of the data");
            clicked => $perform_operation();

            layout {
              column: 0;
              row: 1;
              column-span: 2;
            }

            Adw.ButtonContent {
              halign: center;
              icon-name: "fast-fourier-transform-symbolic";
              label: _("FFT");
            }
          }

          Button inverse_fft_button {
            sensitive: bind shift_button.sensitive;
            tooltip-text: _("Get the Inverse Fast Fourier Transform of the data");
            clicked => $perform_operation();

            layout {
              column: 0;
              row: 2;
              column-span: 2;
            }

            Adw.ButtonContent {
              halign: center;
              icon-name: "inverse-fast-fourier-transform-symbolic";
              label: _("Inverse FFT");
            }
          }

          Button custom_transformation_button {
            sensitive: bind shift_button.sensitive;
            tooltip-text: _("Perform custom transformations on the data");
            clicked => $perform_operation();

            layout {
              column: 0;
              row: 3;
              column-span: 2;
            }

            Adw.ButtonContent {
              halign: center;
              icon-name: "transform-symbolic";
              label: _("Custom Transformation");
            }
          }
        }
      };
    }

    Adw.ViewStackPage {
      title: _("Modify");

      child: Adw.PreferencesGroup {
        Grid {
          column-spacing: 10;
          row-spacing: 10;

          Entry translate_x_entry {
            max-width-chars: 6;
            hexpand: true;
            text: "10";

            layout {
              column: 0;
              row: 0;
            }
          }

          Button translate_x_button {
            valign: center;
            clicked => $perform_operation();
            width-request: 120;

            layout {
              column: 1;
              row: 0;
            }

            Adw.ButtonContent {
              icon-name: "horizontal-arrows-symbolic";
              label: _("Translate X");
            }
          }

          Entry translate_y_entry {
            max-width-chars: 6;
            hexpand: true;
            text: "10";

            layout {
              column: 0;
              row: 1;
            }
          }

          Button translate_y_button {
            valign: center;
            clicked => $perform_operation();
            width-request: 120;

            layout {
              column: 1;
              row: 1;
            }

            Adw.ButtonContent {
              icon-name: "vertical-arrows-symbolic";
              label: _("Translate Y");
            }
          }

          Entry multiply_x_entry {
            max-width-chars: 6;
            hexpand: true;
            text: "10";

            layout {
              column: 0;
              row: 2;
            }
          }

          Button multiply_x_button {
            valign: center;
            clicked => $perform_operation();
            width-request: 120;

            layout {
              column: 1;
              row: 2;
            }

            Adw.ButtonContent {
              icon-name: "horizontal-arrows-symbolic";
              label: _("Multiply X");
            }
          }

          Entry multiply_y_entry {
            max-width-chars: 6;
            hexpand: true;
            text: "10";

            layout {
              column: 0;
              row: 3;
            }
          }

          Button multiply_y_button {
            valign: center;
            clicked => $perform_operation();
            width-request: 120;

            layout {
              column: 1;
              row: 3;
