using Gtk 4.0;
using Adw 1;

template $GraphsStyleEditor: Adw.ApplicationWindow {
  title: _("Graphs Style Editor");
  default-width: 1200;
  default-height: 700;
  width-request: 360;
  height-request: 200;

  ShortcutController {
    Shortcut {
      trigger: "<control>w";
      action: "action(window.close)";
    }

    Shortcut {
      trigger: "<control>question";
      action: "action(win.show-shortcuts)";
    }

    Shortcut {
      trigger: "<control>S";
      action: "action(win.save-style)";
    }

    Shortcut {
      trigger: "<control><shift>S";
      action: "action(win.save-style-as)";
    }

    Shortcut {
      trigger: "<control>O";
      action: "action(win.open-style)";
    }
  }

  Adw.Breakpoint {
    condition ("max-width: 720sp and min-height: 530sp")

    setters {
      multi_layout_view.layout: bottom_sheet_layout;
      editor_headerbar.show-end-title-buttons: true;
      style_grid.max-columns: 2;
      style_menu_button.visible: true;
    }
  }

  Adw.Breakpoint {
    condition ("max-width: 720sp and max-height: 530sp")

    setters {
      multi_layout_view.layout: bottom_sheet_layout;
      editor_headerbar.show-end-title-buttons: true;
      style_grid.max-columns: 2;
      style_menu_button.visible: true;
      sheet_box.height-request: 200;
    }
  }

  content: Stack stack {
    StackPage {
      child: Adw.ToolbarView {
        [top]
        Adw.HeaderBar {
          title-widget: Adw.WindowTitle {
            title: _("Graphs Style Editor");
          };

          [end]
          MenuButton {
            icon-name: "open-menu-symbolic";
            menu-model: empty_menu;
            tooltip-text: _("Open Application Menu");
            primary: true;
          }
        }

        [bottom]
        Adw.Clamp {
          child: Box {
            margin-start: 12;
            margin-end: 12;
            margin-top: 12;
            margin-bottom: 12;
            spacing: 24;
            homogeneous: true;

            MenuButton style_menu_button {
              icon-name: "list-add-symbolic";
              tooltip-text: _("Add New Style");
              always-show-arrow: true;
              visible: false;

              popover: PopoverMenu {
                menu-model: style_menu;
              };

              styles [
                "pill",
              ]
            }

            Button {
              label: _("Import File…");
              halign: center;
              action-name: "win.import-style";
              visible: bind style_menu_button.visible inverted;

              styles [
                "pill",
              ]
            }

            Button {
              label: _("Create Style…");
              halign: center;
              action-name: "win.create-style";
              visible: bind style_menu_button.visible inverted;

              styles [
                "pill",
                "suggested-action",
              ]
            }

            Button {
              label: _("Open File…");
              halign: center;
              action-name: "win.open-style";
              visible: bind style_menu_button.visible inverted;

              styles [
                "pill",
              ]
            }
          };
        }

        content: Adw.Clamp {
          child: ScrolledWindow {
            child: Viewport {
              child: GridView style_grid {
                min-columns: bind style_grid.max-columns;
                max-columns: 3;

                styles [
                  "style-grid",
                ]
              };
            };
          };
        };
      };
    }

    StackPage {
      child: Adw.MultiLayoutView multi_layout_view {
        Adw.Layout side_by_side_layout {
          name: "side-by-side";

          content: Box {
            orientation: horizontal;
            homogeneous: true;

            Box {
              orientation: horizontal;

              Adw.LayoutSlot {
                id: "editor";
              }

              Separator {}
            }

            Adw.ToolbarView content_view {
              styles [
                "canvas-view",
              ]

              [top]
              Adw.HeaderBar {
                name: "preview-headerbar";
                show-start-title-buttons: false;
                show-title: false;
              }

              content: Adw.LayoutSlot {
                id: "canvas";
              };
            }
          };
        }

        Adw.Layout bottom_sheet_layout {
          name: "bottom-sheet";

          content: Adw.BottomSheet bottom_sheet {
            content: Adw.Bin {
              margin-bottom: bind bottom_sheet.bottom-bar-height;

              child: Adw.LayoutSlot {
                id: "editor";
              };
            };

            bottom-bar: CenterBox {
              height-request: 46;

              center-widget: Label {
                label: _("Open Preview");
              };
            };

            sheet: Box sheet_box {
              orientation: vertical;
              height-request: 500;

              Separator {
                margin-top: 36;
                orientation: horizontal;
              }

              Adw.LayoutSlot {
                id: "canvas";
              }
            };
          };
        }

        [editor]
        Adw.ToolbarView {
          [top]
          Adw.HeaderBar editor_headerbar {
            show-end-title-buttons: false;

            title-widget: Adw.WindowTitle {
              title: _("Graphs Style Editor");
            };

            [end]
            MenuButton {
              icon-name: "open-menu-symbolic";
              menu-model: primary_menu;
              tooltip-text: _("Open Application Menu");
              primary: true;
            }
          }

          content: ScrolledWindow {
            hscrollbar-policy: never;

            child: Viewport {
              child: Adw.Clamp {
                margin-bottom: 12;
                margin-top: 12;
                margin-start: 12;
                margin-end: 12;

                child: Adw.Bin editor_bin {};
              };
            };
          };
        }

        [canvas]
        Adw.Bin canvas_bin {
          child: Adw.StatusPage {
            icon-name: "dialog-error-symbolic";
            title: _("Canvas Failed to Load");
          };
        }
      };
    }
  };
}

